/* إطار بزوايا مقعّرة: o = إزاحة الخط إلى الداخل، r = نصف قطر الزاوية عند الإزاحة صفر */
const NOTCH=(o,r)=>{const R=r+o,d=+Math.sqrt(R*R-o*o).toFixed(1),L=36,Rt=1364,T=36,B=954;return `M${L+d} ${T+o}H${Rt-d}A${R} ${R} 0 0 0 ${Rt-o} ${T+d}V${B-d}A${R} ${R} 0 0 0 ${Rt-d} ${B-o}H${L+d}A${R} ${R} 0 0 0 ${L+o} ${B-d}V${T+d}A${R} ${R} 0 0 0 ${L+d} ${T+o}Z`};
function buildStyle(d,k,i=0){
 const m=d.bgs[i].motif;
 if(k==='paper'){const dk=mix(d.accent,'#000000',.42);
  return {bg:mix('#ffffff',d.accent,.14),color:dk,sw:['#fbfaf6',dk],vars:{ink:'#15233d',soft:'#3e4d66',mute:'#6a7a92',gold:'#a8812c',panel:'#ffffff'},
   art:G('pp',mix('#ffffff',d.accent,.04),mix('#ffffff',d.accent,.14))+`<g style="color:${dk}" opacity=".9">${m}</g>`+RR(dk,0,.8)+CO(`<path d="M50 120V50H120" fill="none" stroke="${dk}" stroke-width="4"/><rect x="62" y="62" width="10" height="10" fill="${dk}"/>`)};}
 if(k==='royal'){const g='#e6c26e';
  return {bg:'#2b0817',color:g,sw:['#541029',g],vars:{ink:'#fff6e6',soft:'#ecd3c4',mute:'#cda594',gold:g,panel:'#3a0c1e'},
   art:G('ro','#541029','#2b0817')+`<radialGradient id="rg" cx=".5" cy=".42" r=".6"><stop stop-color="${g}" stop-opacity=".14"/><stop offset="1" stop-color="${g}" stop-opacity="0"/></radialGradient><rect width="1400" height="990" fill="url(#rg)"/><g style="color:${g}" opacity=".7">${m}</g>`+RR(g,0,.9)+CO(`<g fill="none" stroke="${g}" stroke-opacity=".75"><path d="M50 130A80 80 0 0 0 130 50"/><path d="M50 100A50 50 0 0 0 100 50"/><path d="M50 70A20 20 0 0 0 70 50"/></g>`)};}
 if(k==='glass'){const c=d.ui||d.accent;
  return {bg:mix('#04070d',c,.06),color:c,sw:[mix('#04070d',c,.12),c],vars:{ink:'#ffffff',soft:'#cfdbea',mute:'#93a8c0',gold:mix(c,'#ffffff',.55),panel:'#0a1424'},
   art:G('gs',mix('#04070d',c,.1),mix('#04070d',c,.03))+`<radialGradient id="oa"><stop stop-color="${c}" stop-opacity=".34"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></radialGradient><circle cx="1220" cy="120" r="430" fill="url(#oa)"/><circle cx="160" cy="880" r="400" fill="url(#oa)"/><g style="color:${c}" opacity=".55">${m}</g><rect x="36" y="36" width="1328" height="918" rx="30" fill="none" stroke="${c}" stroke-opacity=".22" stroke-width="12"/><rect x="36" y="36" width="1328" height="918" rx="30" fill="none" stroke="${c}" stroke-opacity=".9" stroke-width="2"/><rect x="52" y="52" width="1296" height="886" rx="20" fill="none" stroke="#fff" stroke-opacity=".12"/>`};}

 if(k==='classic'){const n='#1e3f78',g='#a37a1c';
  return {bg:'#fbf5e4',color:'#8a6612',sw:['#fbf5e4',n],vars:{ink:'#0f1f3d',soft:'#34456a',mute:'#62728f',gold:'#8f6a14',panel:'#ffffff'},
   art:G('cl','#fffaf0','#f1e5c6')+`<radialGradient id="clv" cx=".5" cy=".5" r=".75"><stop offset=".6" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#b8903a" stop-opacity=".24"/></radialGradient><rect width="1400" height="990" fill="url(#clv)"/><pattern id="clp" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M11 0 22 11 11 22 0 11Z" fill="none" stroke="${g}" stroke-opacity=".1"/></pattern><rect width="1400" height="990" fill="url(#clp)"/><g fill="none" stroke="${n}" stroke-opacity=".07" stroke-width="1.2" transform="translate(700 495)">`+Array.from({length:24},(_,i)=>`<ellipse rx="330" ry="120" transform="rotate(${i*7.5})"/>`).join('')+`<circle r="345" stroke-opacity=".1" stroke-width="2"/><circle r="332" stroke-dasharray="2 8"/></g><g style="color:${g}" opacity=".5">${m}</g><rect x="36" y="36" width="1328" height="918" fill="none" stroke="${n}" stroke-width="7"/><rect x="50" y="50" width="1300" height="890" fill="none" stroke="${g}" stroke-width="2.5"/><rect x="43" y="43" width="1314" height="904" fill="none" stroke="${n}" stroke-opacity=".6"/>`+CO(`<g fill="none" stroke="${g}"><path d="M74 74H144M74 74V144" stroke-width="3"/><path d="M74 122A48 48 0 0 0 122 74" stroke-width="1.6"/></g><g fill="${g}"><path d="M74 63 85 74 74 85 63 74Z"/><circle cx="144" cy="74" r="3.5"/><circle cx="74" cy="144" r="3.5"/></g>`)};}
 if(k==='emerald'){const g='#e6c26e';
  return {bg:'#04251d',color:g,sw:['#0b6a56',g],vars:{ink:'#fff9ea',soft:'#d2eadf',mute:'#98c8b5',gold:'#f2d27e',panel:'#07382d'},
   art:`<radialGradient id="emg" cx=".5" cy=".4" r=".85"><stop stop-color="#0e7a62"/><stop offset=".55" stop-color="#064a3b"/><stop offset="1" stop-color="#021710"/></radialGradient><rect width="1400" height="990" fill="url(#emg)"/><pattern id="emp" width="80" height="80" patternUnits="userSpaceOnUse"><path d="M40 0 80 40 40 80 0 40Z" fill="none" stroke="${g}" stroke-opacity=".09" stroke-width="1.4"/><circle cx="40" cy="40" r="7" fill="none" stroke="${g}" stroke-opacity=".07"/></pattern><rect width="1400" height="990" fill="url(#emp)"/><g transform="translate(700 495)" fill="${g}" fill-opacity=".03" stroke="${g}" stroke-opacity=".13" stroke-width=".28"><path transform="scale(7.4)" d="${STAR}"/><path transform="scale(5.2) rotate(22.5)" d="${STAR}" fill="none"/></g><g style="color:${g}" opacity=".55">${m}</g><path d="${NOTCH(0,56)}" fill="none" stroke="${g}" stroke-width="3"/><path d="${NOTCH(14,56)}" fill="none" stroke="${g}" stroke-opacity=".55" stroke-width="1.3"/><path d="${NOTCH(24,56)}" fill="none" stroke="${g}" stroke-opacity=".3" stroke-dasharray="2 9"/>`+CO(`<path transform="translate(54 54) scale(.3)" d="${STAR}" fill="${g}"/>`)};}
 return {bg:d.bg,color:d.accent,sw:[d.bg,d.ui||d.accent],vars:d.vars,art:i===0?d.art:G('sg',d.grad[0],d.grad[1])+`<g style="color:${d.accent}">${m}</g>`+RR(d.frame||d.accent,16,.5)};
}

